fn is_power_of_two(n: Int) -> Bool
  requires: n > 0;
  ensures: result == (n & (n - 1) == 0);
{
  return (n & (n - 1)) == 0;
}

fn main() -> Int {
  if is_power_of_two(8) { return 1; }
  return 0;
}
